63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
74	     * owner's id, customer code and registration date, so the create side-effect can be audited
75	     * independently of the application log.
76	     */
77	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
78	
79	    private final ClinicService clinicService;
80	
81	    private final OwnerMapper ownerMapper;
82	
83	    private final PetMapper petMapper;
84	
85	    private final VisitMapper visitMapper;
86	
87	    /**
88	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
89	     * and a domain containing at least one dot, with no whitespace in any segment.
90	     */
91	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
92	
93	    /**
94	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
95	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
96	     */
97	    private static final int MAX_OWNERS_PER_CITY = 50;
98	
99	    /**
100	     * Maximum number of owners that may be registered on a single day (by registration date). A create
101	     * attempted once this many owners already carry today's registration date is rejected with a
102	     * 429 Too Many Requests.
103	     */
104	    private static final int MAX_OWNERS_PER_DAY = 100;
105	
106	    /**
107	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
108	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
109	     */
110	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
111	        "ST", "STREET",
112	        "RD", "ROAD",
113	        "AVE", "AVENUE");
114	
115	    public OwnerRestControllerV1(ClinicService clinicService,
116	                                 OwnerMapper ownerMapper,
117	                                 PetMapper petMapper,
118	                                 VisitMapper visitMapper) {
119	        this.clinicService = clinicService;
120	        this.ownerMapper = ownerMapper;
121	        this.petMapper = petMapper;
122	        this.visitMapper = visitMapper;
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
128	        Collection<Owner> owners;
129	        if (lastName != null) {
130	            owners = this.clinicService.findOwnerByLastName(lastName);
131	        } else {
132	            owners = this.clinicService.findAllOwners();
133	        }
134	        if (owners.isEmpty()) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
153	        validateRequiredFields(ownerFieldsDto);
154	        HttpHeaders headers = new HttpHeaders();
155	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
156	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
157	        owner.setRegistrationDate(registrationDate);
158	        requireDailyCapacity(registrationDate);
159	        requireCityHasCapacity(owner.getCity());
160	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
161	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
162	            joinHousehold(owner);
163	        } else {
164	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
165	        }
166	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
167	        requireUniqueTelephone(telephone);
168	        owner.setTelephone(telephone);
169	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
170	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
171	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
172	        this.clinicService.saveOwner(owner);
173	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
174	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
175	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
176	        headers.setLocation(UriComponentsBuilder.newInstance()
177	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
178	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
179	    }
180	
181	    /**
182	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
183	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
184	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
185	     * existed prior to this create.
186	     *
187	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
188	     *     a business day
189	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
190	     *     registered on that business day
191	     */
192	    private void requireDailyCapacity(LocalDate registrationDate) {
193	        long dayOwnerCount = this.clinicService.findAllOwners().stream()
194	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
195	            .count();
196	        if (dayOwnerCount >= MAX_OWNERS_PER_DAY) {
197	            throw new DailyOwnerLimitException(registrationDate);
198	        }
199	    }
200	
201	    /**
202	     * Rejects an owner whose city already contains the maximum allowed number of owners
203	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
204	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
205	     * create.
206	     *
207	     * @param city the city of the owner being created
208	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
209	     */
210	    private void requireCityHasCapacity(String city) {
211	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
212	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
213	            .count();
214	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
215	            throw new CityOwnerLimitException(city);
216	        }
217	    }
218	
219	    /**
220	     * Generates the customer code for a newly created owner, formatted
221	     * {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3} is the upper-cased first three letters of the
222	     * city, {@code LAST3} the upper-cased first three letters of the last name, and {@code NNNN} a
223	     * per-city, 4-digit zero-padded sequence equal to one more than the number of owners already in
224	     * that city (e.g. {@code 'LON-SMI-0007'}).
225	     *
226	     * @param city the owner's city
227	     * @param lastName the owner's last name
228	     * @return the generated customer code
229	     */
230	    private String generateCustomerCode(String city, String lastName) {
231	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
232	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
233	        int sequence = (int) this.clinicService.findAllOwners().stream()
234	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
235	            .count() + 1;
236	        return String.format("%s-%s-%04d", city3, last3, sequence);
237	    }
238	
239	    /**
240	     * Counts the existing owners that already share the given first name and last name, compared
241	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
242	     * owners that existed prior to this create.
243	     *
244	     * @param firstName the first name of the owner being created
245	     * @param lastName the last name of the owner being created
246	     * @return the number of pre-existing namesakes
247	     */
248	    private int countNamesakes(String firstName, String lastName) {
249	        return (int) this.clinicService.findAllOwners().stream()
250	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
251	                && equalsIgnoreCase(existing.getLastName(), lastName))
252	            .count();
253	    }
254	
255	    /**
256	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
257	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
258	     *
259	     * @param a the first value, possibly {@code null}
260	     * @param b the second value, possibly {@code null}
261	     * @return whether the values are equal ignoring case
262	     */
263	    private boolean equalsIgnoreCase(String a, String b) {
264	        return a == null ? b == null : a.equalsIgnoreCase(b);
265	    }
266	
267	    /**
268	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
269	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
270	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
271	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
272	     *
273	     * @param ownerFieldsDto the submitted owner fields
274	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
275	     */
276	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
277	        List<String> invalidFields = new ArrayList<>();
278	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
279	            invalidFields.add("firstName");
280	        }
281	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
282	            invalidFields.add("lastName");
283	        }
284	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
285	            invalidFields.add("address");
286	        }
287	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
288	            invalidFields.add("city");
289	        }
290	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
291	            invalidFields.add("telephone");
292	        }
293	        if (!invalidFields.isEmpty()) {
294	            throw new InvalidOwnerFieldsException(invalidFields);
295	        }
296	    }
297	
298	    /**
299	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
300	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
301	     * what gets stored and returned.
302	     *
303	     * @param telephone the raw telephone value from the request
304	     * @return the normalized E.164 telephone number
305	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
306	     */
307	    private String normalizeTelephone(String telephone) {
308	        String e164 = toE164(telephone);
309	        if (e164 == null) {
310	            throw new InvalidOwnerFieldsException(List.of("telephone"));
311	        }
312	        return e164;
313	    }
314	
315	    /**
316	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
317	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
318	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
319	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
320	     * it contains 8 to 15 digits after the {@code '+'}.
321	     *
322	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
323	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
324	     *
325	     * @param telephone the raw telephone value, possibly {@code null}
326	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
327	     */
328	    private String toE164(String telephone) {
329	        if (telephone == null) {
330	            return null;
331	        }
332	        String cleaned = telephone.replaceAll("[ \\-()]", "");
333	        String digits;
334	        if (cleaned.startsWith("+")) {
335	            digits = cleaned.substring(1);
336	        } else {
337	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
338	            digits = "61" + national;
339	        }
340	        if (!digits.matches("[0-9]{8,15}")) {
341	            return null;
342	        }
343	        return "+" + digits;
344	    }
345	
346	    /**
347	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
348	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
349	     * and returned lower-cased.
350	     *
351	     * @param email the raw email value from the request, possibly {@code null}
352	     * @return the lower-cased email, or {@code null} when none was supplied
353	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
354	     */
355	    private String normalizeEmail(String email) {
356	        if (!StringUtils.hasText(email)) {
357	            return null;
358	        }
359	        String trimmed = email.trim();
360	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
361	            throw new InvalidOwnerFieldsException(List.of("email"));
362	        }
363	        return trimmed.toLowerCase(Locale.ROOT);
364	    }
365	
366	    /**
367	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
368	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
369	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
370	     *
371	     * @param telephone the normalized (E.164) telephone of the owner being created
372	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
373	     */
374	    private void requireUniqueTelephone(String telephone) {
375	        boolean inUse = this.clinicService.findAllOwners().stream()
376	            .map(Owner::getTelephone)
377	            .filter(existing -> existing != null)
378	            .map(existing -> {
379	                String e164 = toE164(existing);
380	                return e164 != null ? e164 : existing;
381	            })
382	            .anyMatch(telephone::equals);
383	        if (inUse) {
384	            throw new DuplicateTelephoneException(telephone);
385	        }
386	    }
387	
388	    /**
389	     * Rejects an owner whose last name and address match those of an existing owner, where both are
390	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
391	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
392	     *
393	     * @param lastName the last name of the owner being created
394	     * @param address the address of the owner being created
395	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
396	     */
397	    private void requireUniqueHousehold(String lastName, String address) {
398	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
399	            throw new DuplicateHouseholdException(lastName, address);
400	        }
401	    }
402	
403	    /**
404	     * Returns the existing owners that belong to the same household as the given last name and
405	     * address, i.e. those whose last name and address match case-insensitively and with runs of
406	     * whitespace collapsed to a single space.
407	     *
408	     * @param lastName the last name to match
409	     * @param address the address to match
410	     * @return the matching owners (possibly empty, never {@code null})
411	     */
412	    private List<Owner> findHouseholdMembers(String lastName, String address) {
413	        String normalizedLastName = normalizeForHousehold(lastName);
414	        String normalizedAddress = normalizeAddress(address);
415	        return this.clinicService.findAllOwners().stream()
416	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
417	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
418	            .toList();
419	    }
420	
421	    /**
422	     * Joins the owner being created to the shared household of any existing owner(s) that have the
423	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
424	     * member of the household - the existing owners and the new one - is assigned the same stable
425	     * {@code householdId}, so the shared identifier can be read back from any of them.
426	     *
427	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
428	     * the owner is left without a {@code householdId}.
429	     *
430	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
431	     */
432	    private void joinHousehold(Owner owner) {
433	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
434	        if (members.isEmpty()) {
435	            return;
436	        }
437	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
438	        owner.setHouseholdId(householdId);
439	        for (Owner member : members) {
440	            if (!householdId.equals(member.getHouseholdId())) {
441	                member.setHouseholdId(householdId);
442	                this.clinicService.saveOwner(member);
443	            }
444	        }
445	    }
446	
447	    /**
448	     * Computes the stable, shared household identifier for a last name and address. The value is
449	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
450	     * name and address, so every owner in the same household computes the same identifier.
451	     *
452	     * @param lastName the last name of the household
453	     * @param address the address of the household
454	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
455	     */
456	    private String computeHouseholdId(String lastName, String address) {
457	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
458	        try {
459	            byte[] digest = MessageDigest.getInstance("SHA-256")
460	                .digest(key.getBytes(StandardCharsets.UTF_8));
461	            StringBuilder hex = new StringBuilder();
462	            for (int i = 0; i < 6; i++) {
463	                hex.append(String.format("%02X", digest[i]));
464	            }
465	            return "HH-" + hex;
466	        } catch (NoSuchAlgorithmException e) {
467	            throw new IllegalStateException("SHA-256 algorithm not available", e);
468	        }
469	    }
470	
471	    /**
472	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
473	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
474	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
475	     *
476	     * @param value the raw value, possibly {@code null}
477	     * @return the normalized value
478	     */
479	    private String normalizeForHousehold(String value) {
480	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
481	    }
482	
483	    /**
484	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
485	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
486	     * value yields an empty string.
487	     *
488	     * @param value the raw value, possibly {@code null}
489	     * @return the trimmed, whitespace-collapsed value
490	     */
491	    private String collapseWhitespace(String value) {
492	        if (value == null) {
493	            return "";
494	        }
495	        return value.trim().replaceAll("\\s+", " ");
496	    }
497	
498	    /**
499	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
500	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
501	     * is upper-cased, and common street-type abbreviations are expanded as whole words
502	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
503	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
504	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
505	     *
506	     * @param address the raw address value, possibly {@code null}
507	     * @return the normalized address
508	     */
509	    private String normalizeAddress(String address) {
510	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
511	        if (collapsed.isEmpty()) {
512	            return "";
513	        }
514	        String[] tokens = collapsed.split(" ");
515	        StringBuilder normalized = new StringBuilder();
516	        for (int i = 0; i < tokens.length; i++) {
517	            if (i > 0) {
518	                normalized.append(' ');
519	            }
520	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
521	        }
522	        return normalized.toString();
523	    }
524	
525	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
526	    @Override
527	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
528	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
529	        if (currentOwner == null) {
530	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
531	        }
532	        currentOwner.setAddress(ownerFieldsDto.getAddress());
533	        currentOwner.setCity(ownerFieldsDto.getCity());
534	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
535	        currentOwner.setLastName(ownerFieldsDto.getLastName());
536	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
537	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
538	        this.clinicService.saveOwner(currentOwner);
539	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
540	    }
541	
542	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
543	    @Transactional
544	    @Override
545	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
546	        Owner owner = this.clinicService.findOwnerById(ownerId);
547	        if (owner == null) {
548	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
549	        }
550	        this.clinicService.deleteOwner(owner);
551	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
552	    }
553	
554	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
555	    @Override
556	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
557	        Owner owner = this.clinicService.findOwnerById(ownerId);
558	        if (owner == null) {
559	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
560	        }
561	        HttpHeaders headers = new HttpHeaders();
562	        Pet pet = petMapper.toPet(petFieldsDto);
563	        owner.setId(ownerId);
564	        pet.setOwner(owner);
565	        pet.getType().setName(null);
566	        this.clinicService.savePet(pet);
567	        PetDto petDto = petMapper.toPetDto(pet);
568	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
569	            .buildAndExpand(pet.getId()).toUri());
570	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
571	    }
572	
573	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
574	    @Override
575	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
576	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
577	        if (currentOwner != null) {
578	            Pet currentPet = this.clinicService.findPetById(petId);
579	            if (currentPet != null) {
580	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
581	                currentPet.setName(petFieldsDto.getName());
582	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
583	                this.clinicService.savePet(currentPet);
584	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
585	            }
586	        }
587	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
588	    }
589	
590	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
591	    @Override
592	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
593	        HttpHeaders headers = new HttpHeaders();
594	        Visit visit = visitMapper.toVisit(visitFieldsDto);
595	        Pet pet = new Pet();
596	        pet.setId(petId);
597	        visit.setPet(pet);
598	        this.clinicService.saveVisit(visit);
599	        VisitDto visitDto = visitMapper.toVisitDto(visit);
600	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
601	            .buildAndExpand(visit.getId()).toUri());
602	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
603	    }
604	
605	
606	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
607	    @Override
608	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
609	        Owner owner = this.clinicService.findOwnerById(ownerId);
610	        if (owner != null) {
611	            Pet pet = owner.getPet(petId);
612	            if (pet != null) {
613	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
614	            }
615	        }
616	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
617	    }
618	}
